// 0.32.0 hub-split: bin/factory/shared.ts, bin/factory/resources.ts and bin/store.ts are split along their callers so a change to one
// no longer selects most of the suite. The measure is the one 0.31.0's report used: selectTests (bin/testmap.ts) on the real tracked
// tree with a one-file diff, the same inputs selectForCheckout builds. The builders pin the layout below; do not edit this file.
import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { test } from 'node:test'
import { selectTests } from '../bin/testmap.ts'

const PLUGIN = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const BIN = path.join(PLUGIN, 'bin')
const ROOT = path.resolve(PLUGIN, '..', '..')
const REL = (p: string): string => path.relative(ROOT, p).replace(/\\/g, '/')
const LIMIT = 50

// Every name the three hubs exported before the split (their `^export` lines at the crew base).
const HUB_EXPORTS = {
  'bin/store.ts': [
    'CliError', 'usage', 'refuse', 'Flags', 'Obj', 'flat', 'str', 'need', 'listOf', 'readText', 'readJson', 'isObj', 'parseLabel', 'configOf',
    'repoPathOf', 'packageName', 'declares', 'git', 'commonDir', 'sharedDir', 'FsLike', 'StoreBusy', 'LockOpts', 'takeOver', 'withLock',
    'writeJsonAtomic', 'createExclusive', 'LEASE_STALE_MS', 'LEASE_REFRESH_MS', 'LeaseOpts', 'takeLease', 'refreshLease', 'releaseLease',
    'appendJsonl', 'readJsonl', 'proofTranscriptRoot', 'readProofFile', 'transcriptsOf',
  ],
  'bin/factory/shared.ts': [
    'PLUGIN', 'FACTORY', 'parseFlags', 'run', 'gitOrFail', 'repoOf', 'startDirOf', 'dirOf', 'loadPlan', 'savePlan', 'patchPlan', 'settingsOf', 'intOr',
    'docKeysOf', 'knowledgeCfgOf', 'knowledgeCfgFrom', 'knowledgeArgsOf', 'crewWorktree', 'baseOf', 'appendEvent', 'appendDecision',
    'appendDecisionLine', 'readRoles', 'roleDefaults', 'rolesWithTypes', 'modelsOf', 'scriptPathFor', 'sessionScriptsDir', 'archPath',
  ],
  'bin/factory/resources.ts': [
    'HEAVY_WAIT_MS', 'HEAVY_WAIT_MAX_MS', 'explicitWaitMs', 'heavyWaitMs', 'slotWaitMs', 'recordHeavyTime', 'acquireSlot', 'slotsAt', 'heavySlotsOf',
    'pidAlive', 'admission', 'cmdAdmit', 'GROUPS', 'cmdReap', 'heldOnBusy',
  ],
}
const NEW_MODULES = [
  'bin/core.ts', 'bin/lock.ts', 'bin/transcripts.ts',
  'bin/factory/cli.ts', 'bin/factory/plan-file.ts', 'bin/factory/settings.ts', 'bin/factory/log.ts', 'bin/factory/roles.ts',
  'bin/factory/slot.ts', 'bin/factory/admit.ts', 'bin/factory/reap.ts',
]
const BARRELS = Object.keys(HUB_EXPORTS)

const git = (args: string[]): string => {
  const r = spawnSync('git', ['-c', 'core.quotepath=off', ...args], { cwd: ROOT, encoding: 'utf8', windowsHide: true, maxBuffer: 64 * 1024 * 1024 })
  assert.equal(r.status, 0, `git ${args.join(' ')} failed: ${r.stderr}`)
  return r.stdout
}
const tracked = git(['ls-files', '-z']).split('\0').filter(Boolean)
const packageTest = ((): string | null => {
  const t = JSON.parse(readFileSync(path.join(ROOT, 'package.json'), 'utf8'))?.scripts?.test
  return typeof t === 'string' && t.trim() !== '' ? t : null
})()
const read = (p: string): string | null => {
  try {
    const f = path.join(ROOT, p)
    return statSync(f).size > 4 * 1024 * 1024 ? null : readFileSync(f, 'utf8')
  } catch {
    return null
  }
}
/** The test files selectTests picks for a one-file change to `rel` (a path under the repo root). Fails when the mode is full. */
function selected(rel: string): string[] {
  const sel = selectTests({ tracked, changed: [{ path: `plugins/truss/${rel}`, deleted: false }], read, config: {}, packageTest })
  assert.equal(sel.mode, 'targeted', `a change to ${rel} selects the full suite: ${sel.why.join('; ')}`)
  return sel.files
}
// the denominator the 0.31.0 report used: every test file package.json's `node --test` globs name
const runnableTotal = tracked.filter((t) => /^plugins\/truss\/tests\/([^/]+\/)?[^/]+\.check\.ts$/.test(t) || /^checks\/[^/]+\.check\.ts$/.test(t)).length

const countMemo = new Map<string, string[]>()
const selectedMemo = (rel: string): string[] => {
  if (!countMemo.has(rel)) countMemo.set(rel, selected(rel))
  return countMemo.get(rel) as string[]
}
/** The names a module declares itself: a declaration, or `export { a }` without `from`. A re-export (`export ... from`, `export *`) declares nothing. */
function ownExports(file: string): Set<string> {
  const out = new Set<string>()
  const text = readFileSync(file, 'utf8')
  for (const m of text.matchAll(/^export\s+(?:declare\s+)?(?:async\s+)?(?:function\*?|const|let|var|class|type|interface)\s+([\w$]+)/gm)) out.add(m[1] as string)
  for (const m of text.matchAll(/^export\s+(?:type\s+)?\{([^}]*)\}(?!\s*from)/gm)) {
    for (const part of (m[1] as string).split(',')) {
      const name = part.trim().split(/\s+as\s+/).pop()?.trim()
      if (name) out.add(name)
    }
  }
  return out
}
/** The module that declares `name` as the hub exports it: the hub itself, or the module its `export ... from` / `export *` lines lead to. */
function homeOf(file: string, name: string, seen = new Set<string>()): string[] {
  if (seen.has(file) || !existsSync(file)) return []
  seen.add(file)
  if (ownExports(file).has(name)) return [file]
  const text = readFileSync(file, 'utf8')
  const out: string[] = []
  for (const m of text.matchAll(/^export\s+(?:type\s+)?(\*|\{[^}]*\})\s+from\s+['"]([^'"]+)['"]/gm)) {
    const listed = m[1] === '*' ? [name] : (m[1] as string).slice(1, -1).split(',').map((p) => p.trim().split(/\s+as\s+/).pop()?.trim())
    if (listed.includes(name)) out.push(...homeOf(path.resolve(path.dirname(file), m[2] as string), name, seen))
  }
  return out
}
/** The real leaves a hub's code lives in now: for each name the hub exported before the split, the module under bin/ that declares it. */
function leavesOf(hub: string): Map<string, string[]> {
  const leaves = new Map<string, string[]>()
  for (const n of HUB_EXPORTS[hub as keyof typeof HUB_EXPORTS]) {
    const hubFile = path.join(PLUGIN, hub)
    // a hub a later goal deletes leaves no re-export to follow: every module under bin/ that declares the name is then its home
    const found = existsSync(hubFile) ? homeOf(hubFile, n) : tsUnder(BIN).filter((f) => ownExports(f).has(n))
    const homes = found.map((f) => REL(f).replace(/^plugins\/truss\//, ''))
    assert.ok(homes.length > 0, `${hub} exported ${n} before the split and neither it nor a module it re-exports declares it now`)
    for (const h of homes) leaves.set(h, [...(leaves.get(h) ?? []), n])
  }
  return leaves
}

/** Test files a one-line change to the hub selected at the crew base, measured then with the same selectTests (R-139 asked for 50; the factory.ts load graph makes that unreachable, see ADR-0049 Consequences). */
const HUB_BASE_COUNT: Record<string, number> = { 'bin/factory/shared.ts': 95, 'bin/factory/resources.ts': 95, 'bin/store.ts': 103 }

/** A one-line change in each leaf the hub's code moved to selects no more test files than the hub did before the split. A leaf no test reaches does not count as small. */
function countCase(hub: string, t: { diagnostic: (m: string) => void }): void {
  const leaves = leavesOf(hub)
  assert.ok(leaves.size > 0, `${hub}: no leaf found`)
  const rows = [...leaves.keys()].sort().map((rel) => ({ rel, n: selectedMemo(rel).length }))
  for (const r of rows) t.diagnostic(`${r.rel}: ${r.n} of ${runnableTotal}`)
  const report = rows.map((r) => `${r.rel}: ${r.n} of ${runnableTotal}`).join('; ')
  const dead = rows.filter((r) => r.n === 0).map((r) => r.rel)
  assert.deepEqual(dead, [], `no test file is selected for a change to ${dead.join(', ')}: a leaf nothing reaches is not a small one (${report})`)
  const limit = HUB_BASE_COUNT[hub] as number
  const worst = rows.reduce((a, b) => (b.n > a.n ? b : a))
  assert.ok(
    worst.n <= limit,
    `a one-line change to ${worst.rel}, a leaf ${hub}'s code moved to, selects ${worst.n} of ${runnableTotal} test files, over ${limit}, the ${hub} count at the crew base. All leaves: ${report}`,
  )
}

test('a change to any leaf of bin/factory/shared.ts selects no more test files than the hub did before the split', (t) => countCase('bin/factory/shared.ts', t))
test('a change to any leaf of bin/factory/resources.ts selects no more test files than the hub did before the split', (t) => countCase('bin/factory/resources.ts', t))
test('a change to any leaf of bin/store.ts selects no more test files than the hub did before the split', (t) => countCase('bin/store.ts', t))

// ---- exports --------------------------------------------------------------------------------------------------------------
function tsUnder(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name)
    return e.isDirectory() ? tsUnder(p) : e.name.endsWith('.ts') ? [p] : []
  })
}
/** The names a module exports: its own declarations, `export { a, b as c } from`, and `export * from` followed to the target. */
function exportsOf(file: string, seen = new Set<string>()): Set<string> {
  const out = new Set<string>()
  if (seen.has(file) || !existsSync(file)) return out
  seen.add(file)
  const text = readFileSync(file, 'utf8')
  for (const m of text.matchAll(/^export\s+(?:declare\s+)?(?:async\s+)?(?:function\*?|const|let|var|class|type|interface)\s+([\w$]+)/gm)) out.add(m[1] as string)
  for (const m of text.matchAll(/^export\s+(?:type\s+)?\{([^}]*)\}/gm)) {
    for (const part of (m[1] as string).split(',')) {
      const name = part.trim().split(/\s+as\s+/).pop()?.trim()
      if (name) out.add(name)
    }
  }
  for (const m of text.matchAll(/^export\s+(?:type\s+)?\*\s+from\s+['"]([^'"]+)['"]/gm)) {
    for (const n of exportsOf(path.resolve(path.dirname(file), m[1] as string), seen)) out.add(n)
  }
  return out
}

test('every name bin/factory/shared.ts, bin/factory/resources.ts and bin/store.ts exported before the split is exported by a module under bin/', () => {
  const have = new Set<string>()
  for (const f of tsUnder(BIN)) for (const n of exportsOf(f)) have.add(n)
  assert.ok(have.has('CliError') && have.has('parseFlags'), 'the export scanner finds nothing: it is vacuous')
  for (const [hub, names] of Object.entries(HUB_EXPORTS)) {
    const missing = names.filter((n) => !have.has(n))
    assert.deepEqual(missing, [], `${hub} exported ${missing.join(', ')} before the split and no module under bin/ exports it now`)
  }
})

// ---- factory.ts imports ---------------------------------------------------------------------------------------------------
const importsFactory = (text: string): string[] =>
  [...text.matchAll(/(?:\bimport|\bexport)\s+(?:type\s+)?(?:[^'"`;]*?\s+from\s+)?['"]([^'"]+)['"]|\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/g)]
    .map((m) => (m[1] ?? m[2]) as string).filter((s) => /(^|\/)factory(\.ts)?$/.test(s))

test('no bin module imports bin/factory.ts after the split', () => {
  assert.deepEqual(importsFactory(`import { main } from '../factory.ts'\n`), ['../factory.ts'], 'the scanner misses a planted import')
  assert.deepEqual(importsFactory(`export * from './factory.ts'\n`), ['./factory.ts'], 'the scanner misses a planted re-export')
  const files = tsUnder(BIN)
  assert.ok(files.length > 30, `only ${files.length} .ts files found under bin/`)
  for (const f of files) assert.deepEqual(importsFactory(readFileSync(f, 'utf8')), [], `${REL(f)} imports factory.ts`)
})

// ---- unpinned: the measure is live, and no one loads a barrel -------------------------------------------------------------
test('hub-split 032: a change to bin/factory.ts still selects more than 50 test files, so the measure is live', () => {
  const files = selected('bin/factory.ts')
  assert.ok(files.length > LIMIT, `a change to bin/factory.ts selects only ${files.length} test files: the count measure no longer separates a hub from a leaf`)
})

test('hub-split 032: no module under bin/ or resources/ imports a barrel; each loads the leaf it uses', () => {
  const importsOf = (text: string): string[] =>
    [...text.matchAll(/(?:\bimport|\bexport)\s+(?:type\s+)?(?:[^'"`;]*?\s+from\s+)?['"]([^'"]+)['"]|\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/g)].map((m) => (m[1] ?? m[2]) as string)
  assert.deepEqual(
    importsOf(`import { x } from '../store.ts'\n`).map((s) => path.posix.normalize(path.posix.join('bin/factory', s))),
    ['bin/store.ts'],
    'the scanner misses a planted barrel import',
  )
  const files = [...tsUnder(BIN), ...(existsSync(path.join(PLUGIN, 'resources')) ? tsUnder(path.join(PLUGIN, 'resources')) : [])]
  const bad: string[] = []
  for (const f of files) {
    if (BARRELS.includes(REL(f).replace(/^plugins\/truss\//, ''))) continue
    for (const s of importsOf(readFileSync(f, 'utf8'))) {
      if (!s.startsWith('.')) continue
      const target = REL(path.resolve(path.dirname(f), s)).replace(/^plugins\/truss\//, '')
      const msg = `${REL(f)} imports the barrel ${target}`
      if (BARRELS.includes(target) && !bad.includes(msg)) bad.push(msg)
    }
  }
  assert.deepEqual(bad, [], `import the leaf module instead (store.ts: core.ts, lock.ts, transcripts.ts; factory/shared.ts: cli, plan-file, settings, log, roles; factory/resources.ts: slot, admit, reap):\n${bad.join('\n')}`)
})

test('hub-split 032: the selection count for each new module (logged for the builders report)', (t) => {
  for (const m of [...BARRELS, 'bin/factory.ts', ...NEW_MODULES]) {
    if (!tracked.includes(`plugins/truss/${m}`)) {
      t.diagnostic(`${m}: not tracked yet`)
      continue
    }
    const sel = selectTests({ tracked, changed: [{ path: `plugins/truss/${m}`, deleted: false }], read, config: {}, packageTest })
    t.diagnostic(`${m}: ${sel.mode === 'targeted' ? `${sel.files.length} of ${runnableTotal}` : `full suite (${sel.why[0]})`}`)
  }
})
